@extends('layouts.app') @section('title',($package->exists?'Edit':'New').' package — PhotoHub') @section('content')<x-page-header :title="$package->exists?'Edit package':'New package'"/><form class="content-card auto-height" method="POST" action="{{ $package->exists?route('packages.update',$package):route('packages.store') }}">@csrf @if($package->exists)@method('PUT')@endif<div class="row g-3">@foreach([['name','Package name','text'],['category','Category','text'],['price','Price','number'],['deposit_amount','Deposit amount','number'],['duration_minutes','Duration (minutes)','number'],['photographers_count','Number of photographers','number'],['photos_count','Total photos','number'],['edited_photos_count','Edited photos','number'],['delivery_days','Delivery days','number']] as [$n,$l,$t])<div class="col-md-6"><label class="form-label">{{ $l }}</label><input type="{{ $t }}" name="{{ $n }}" value="{{ old($n,$package->$n??($n==='duration_minutes'?60:($n==='photographers_count'?1:($n==='delivery_days'?14:0)))) }}" class="form-control" {{ in_array($n,['name','category','price','deposit_amount','duration_minutes','photographers_count','delivery_days'])?'required':'' }}></div>@endforeach<div class="col-12"><label class="form-label">Description</label><textarea name="description" class="form-control" rows="4">{{ old('description',$package->description) }}</textarea></div><div class="col-12 d-flex flex-wrap gap-4">@foreach(['album_included'=>'Album','video_included'=>'Video','drone_included'=>'Drone','prints_included'=>'Prints','is_active'=>'Active'] as $n=>$l)<label class="form-check"><input class="form-check-input" type="checkbox" name="{{ $n }}" value="1" @checked(old($n,$package->exists?$package->$n:$n==='is_active'))> {{ $l }}</label>@endforeach</div></div><button class="btn btn-primary mt-4">Save package</button></form>@endsection
